-- ------------------------------------------------------------
-- American Samoa (AS)
-- ------------------------------------------------------------
INSERT INTO auth.cities (name, country_id)
SELECT v.name, c.id
FROM auth.countries c
JOIN (VALUES
    ('Pago Pago')
) AS v(name) ON c.code = 'AS'
ON CONFLICT (name, country_id) DO NOTHING;

