-- ------------------------------------------------------------
-- French Guiana (GF)
-- ------------------------------------------------------------
INSERT INTO auth.cities (name, country_id)
SELECT v.name, c.id
FROM auth.countries c
JOIN (VALUES
	('Cayenne'),
	('Iracoubo'),
	('Kourou'),
	('Roura'),
	('Saint-Georges'),
	('Saint-Laurent-du-Maroni'),
	('Sinnamary')
) AS v(name) ON c.code = 'GF'
ON CONFLICT (name, country_id) DO NOTHING;

-- ------------------------------------------------------------
-- French Polynesia (PF)
-- ------------------------------------------------------------
INSERT INTO auth.cities (name, country_id)
SELECT v.name, c.id
FROM auth.countries c
JOIN (VALUES
	('Papeete')
) AS v(name) ON c.code = 'PF'
ON CONFLICT (name, country_id) DO NOTHING;

