-- ------------------------------------------------------------
-- Jamaica (JM)
-- ------------------------------------------------------------
INSERT INTO auth.cities (name, country_id)
SELECT v.name, c.id
FROM auth.countries c
JOIN (VALUES
	('Black River'),
	('Bog Walk'),
	('Ewarton'),
	('Falmouth'),
	('Half Way Tree'),
	('Linstead'),
	('Lucea'),
	('Lucky Hill'),
	('Mandeville'),
	('May Pen'),
