-- ------------------------------------------------------------
-- Saint Barthelemy (BL)
-- ------------------------------------------------------------
INSERT INTO auth.cities (name, country_id)
SELECT v.name, c.id
FROM auth.countries c
JOIN (VALUES
	('Gustavia')
) AS v(name) ON c.code = 'BL'
ON CONFLICT (name, country_id) DO NOTHING;

-- ------------------------------------------------------------
-- Saint Helena, Ascension and Tristan da Cunha (SH)
-- ------------------------------------------------------------
INSERT INTO auth.cities (name, country_id)
SELECT v.name, c.id
FROM auth.countries c
JOIN (VALUES
	('Edinburgh of the Seven Seas'),
	('Georgetown'),
	('Jamestown')
) AS v(name) ON c.code = 'SH'
ON CONFLICT (name, country_id) DO NOTHING;

-- ------------------------------------------------------------
-- Saint Kitts and Nevis (KN)
-- ------------------------------------------------------------
INSERT INTO auth.cities (name, country_id)
SELECT v.name, c.id
FROM auth.countries c
JOIN (VALUES
    ('Basseterre')
) AS v(name) ON c.code = 'KN'
ON CONFLICT (name, country_id) DO NOTHING;

-- ------------------------------------------------------------
-- Saint Lucia (LC)
-- ------------------------------------------------------------
INSERT INTO auth.cities (name, country_id)
SELECT v.name, c.id
FROM auth.countries c
JOIN (VALUES
	('Bisee'),
	('Castries'),
	('Gros Islet'),
	('Micoud'),
	('Vieux Fort')
) AS v(name) ON c.code = 'LC'
ON CONFLICT (name, country_id) DO NOTHING;

