	('Zymohiria')
) AS v(name) ON c.code = 'UA'
ON CONFLICT (name, country_id) DO NOTHING;

-- ------------------------------------------------------------
-- United Arab Emirates (AE)
-- ------------------------------------------------------------
INSERT INTO auth.cities (name, country_id)
SELECT v.name, c.id
FROM auth.countries c
JOIN (VALUES
	('‘Ajmān'),
	('Abu Dhabi'),
	('Al ‘Ayn'),
	('Al Fujayrah'),
	('Al Jazīrah al Ḩamrā’'),
	('Dubai'),
	('Kalbā'),
	('Khawr Fakkān'),
	('Madīnat Zāyid'),
	('Ra’s al Khaymah'),
	('Sharjah'),
	('Umm al Qaywayn')
) AS v(name) ON c.code = 'AE'
ON CONFLICT (name, country_id) DO NOTHING;

